[5063] = { en = "Cap of the Scarlet Savant", tier = 4,
  t = "Cap of the Scarlet Savant",
  d = "Een mooiere muts zul je misschien nooit zien. Van de gave huid van het beest maken onze ervaren vaklieden de meest fantastische hoed die een goochelaar ooit zou kunnen dragen!$B$BVijftig goudstukken en de genoemde voorwerpen, en dan zal de Cap of the Scarlet Savant je hoofd sieren:$B$B*De gave huid van het beest.$B$B*Gerafelde hechtingen van gruwelen.$B$B*Arcane kristallen.$B$B*Betoverde scharlakenrode draad.$B$BAANSCHOUW!",
  o = "Om de Cap of the Scarlet Savant te maken, moet je de volgende voorwerpen naar Malyfous Darkhammer brengen: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.$B$BJe moet ook 50 goudstukken betalen voor het maken van het voorwerp.",
  p = "Als je niet alles hebt wat ik nodig heb, verspil je mijn tijd.",
  c = "Verbazingwekkend! Het moet weken hebben geduurd om die onderdelen te verzamelen... En hoe heb je een gave huid gevonden?!?$b$bVeel plezier met de muts, $n!",
  g = { {"gave", "undamaged, flawless (gaaf)"}, {"vaklieden", "craftsmen (vakman)"}, {"goochelaar", "conjurer, magician"}, {"sieren", "to adorn"}, {"gerafelde", "frayed (gerafeld)"}, {"hechtingen", "stitchings (hechting)"}, {"gruwelen", "abominations (gruwel)"}, {"scharlakenrode", "scarlet (scharlakenrood)"}, {"aanschouw", "behold (aanschouwen)"}, {"verbazingwekkend", "astounding"}, {"verspil", "waste (verspillen)"} },
},

[5067] = { en = "Leggings of Arcana", tier = 4,
  t = "Leggings of Arcana",
  d = "Het is nog nooit gelukt om zo'n voorwerp te maken. Toch denkt men dat het mogelijk is, onder de juiste omstandigheden.$B$BAls de zoeker naar geheime kennis een beenkleed met enorme kracht wil vullen, moet hij het volgende vinden:$B$B* De gave huid van het beest.$B$B* Gerafelde hechtingen van gruwelen.$B$B* Staven arcaniet.$B$B* Frostwhispers balsemvloeistof.$B$BAANSCHOUW!",
  o = "Om de Leggings of Arcana te maken, moet je de volgende voorwerpen naar Malyfous Darkhammer brengen: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.$B$BJe moet ook 50 goudstukken betalen voor het maken van het voorwerp.",
  p = "Als je niet alles hebt wat ik nodig heb, verspil je mijn tijd.",
  c = "Ik heb maar weinig taken gezien die onwaarschijnlijker waren en toch door stervelingen zijn volbracht. Geniet van de glorie van mijn vakwerk! Pluk er de vruchten van!",
  g = { {"omstandigheden", "circumstances (omstandigheid)"}, {"geheime kennis", "arcane knowledge"}, {"beenkleed", "leggings, leg armour"}, {"staven", "bars (staaf)"}, {"balsemvloeistof", "embalming fluid"}, {"onwaarschijnlijker", "more improbable (onwaarschijnlijk)"}, {"stervelingen", "mortals (sterveling)"}, {"volbracht", "accomplished (volbrengen)"}, {"vakwerk", "handiwork, craftsmanship"}, {"pluk er de vruchten van", "reap the rewards"} },
},

[5122] = { en = "The Medallion of Faith", tier = 4,
  t = "The Medallion of Faith",
  p = "De kracht van deze kapel geeft me de sterkte om de verdorvenheid in mijn hart te weerstaan. Als ik de kapel verlaat, word ik een doodsridder. Maar er is een medaillon, het medaillon van het geloof, dat me de kracht zal geven die ik nodig heb om te vertrekken.$B$BAlsjeblieft, $N, haal het medaillon op. Het wordt bewaakt door Malor the Zealous, een waanzinnig lid van de Scarlet Brotherhood. Hij woont diep in de Scarlet Bastion, in het westen van Stratholme.",
  c = "Je hebt het medaillon teruggevonden! Nu kan ik de kapel verlaten en mijn plicht doen.$B$BDie plicht is het beest doden dat mij en zoveel van mijn broeders en zusters heeft helpen bederven: Baron Rivendare!",
  g = { {"kapel", "chapel"}, {"verdorvenheid", "corruption"}, {"weerstaan", "to resist"}, {"doodsridder", "death knight"}, {"geloof", "faith"}, {"bewaakt", "guarded (bewaken)"}, {"waanzinnig", "crazed, insane"}, {"plicht", "duty"}, {"bederven", "to corrupt, to spoil"} },
},

[5125] = { en = "Aurius' Reckoning", tier = 4,
  t = "Aurius' Reckoning",
  c = "$N, ik ga dood... maar mijn ziel is gered. Daarvoor ben ik je meer schuldig dan woorden kunnen zeggen. Alsjeblieft, neem dit aan... en blijf vechten, dappere $c!",
  g = { {"ziel", "soul"}, {"gered", "saved (redden)"}, {"schuldig", "owing, indebted"}, {"dappere", "brave (dapper)"} },
