[5212] = { en = "The Flesh Does Not Lie", tier = 4,
  t = "Het vlees liegt niet",
  d = "De apothekers van de Forsaken zijn niet de enige wezens op deze wereld die in de wetenschappen geschoold zijn.$B$BIk bestudeer de pest al jaren, $r. Eerst dachten we dat de kracht van de pest afnam, maar wat ik hier in de Plaguelands heb ontdekt, is schrikbarend. De pest lijkt sterker te worden!$B$BIk moet meer proeven doen! De sterkste bron van de pest is het besmette vlees van degenen die het laatst zijn geïnfecteerd. Reis naar Stratholme en breng me monsters, $N.$b",
  o = "Haal 20 Plagued Flesh Samples uit Stratholme en breng ze terug naar Betina Bigglezink. Je vermoedt dat elk wezen in Stratholme zo'n vleesmonster bij zich heeft.",
  p = "Sommigen zeggen dat ik me te veel zorgen maak. Tegen hen zeg ik: 'Jullie maken je niet genoeg zorgen!'",
  c = "Er is iets veranderd in de chemische samenstelling van de werkzame stoffen van de pest. Er zijn meer gegevens nodig.",
  g = { {"apothekers", "apothecaries (apotheker)"}, {"geschoold", "schooled, trained"}, {"pest", "plague"}, {"afnam", "was dwindling (afnemen)"}, {"schrikbarend", "startling, alarming"}, {"proeven", "tests, experiments (proef)"}, {"besmette", "infected, tainted (besmet)"}, {"monsters", "samples (monster)"}, {"vermoedt", "suspect (vermoeden)"}, {"samenstelling", "structure, composition"}, {"werkzame stoffen", "active agents"}, {"gegevens", "data"} },
},

[5213] = { en = "The Active Agent", tier = 4,
  t = "De werkzame stof",
  d = "Je zult dieper in Stratholme moeten doordringen, $N.$B$BVoorbij de eerste poorten vind je de ziggurats. We weten dat de Scourge veel kracht haalt uit deze bouwwerken. Doorzoek de ziggurats en kom terug met alle informatie die je kunt ontdekken.$b",
  o = "Reis naar Stratholme en doorzoek de ziggurats. Vind nieuwe Scourge Data en breng die terug naar Betina Bigglezink.$b",
  p = "We staan op het punt om te ontdekken wat deze nieuwe werkzame stof van de pest is!",
  c = "Verbluffend! Het zal maanden duren om dit te ontleden en te analyseren. De Argent Dawn dankt je voor je moeite, $N.$B$BKies met onze zegen tussen dit Seal of the Dawn en deze Rune of the Dawn. Je kunt ze allebei gebruiken in plaats van een gewone Argent Dawn Commission om voor ons scourgestones te verzamelen. Als je de jouwe kwijtraakt, praat dan met mij. Dan zorg ik voor een nieuwe.",
  g = { {"doordringen", "to penetrate, to delve"}, {"poorten", "gates (poort)"}, {"bouwwerken", "structures (bouwwerk)"}, {"doorzoek", "search (doorzoeken)"}, {"op het punt staan", "to be on the verge"}, {"verbluffend", "astonishing"}, {"ontleden", "to dissect"}, {"zegen", "blessing"}, {"kwijtraakt", "lose (kwijtraken)"} },
},

[5214] = { en = "The Great Fras Siabi", tier = 4,
  t = "De grote Fras Siabi",
  d = "Vreselijk... wat er met Fras is gebeurd. Zie je, de stad werd geplunderd en Fras wilde zijn kostbare waren niet achterlaten. Het laatste wat ik hem hoorde zeggen was: 'Ik verbrand elk laatste blaadje voordat ze er hun verdomde, smerige handen op leggen!'$B$BIk hou dan wel van een goede sigaar, maar ik ben niet gek. Ik heb Fras en zijn heerlijke winkel die dag verlaten. Ik neem aan dat hij in de vlammen is omgekomen. Maar als er een kans is dat zelfs maar één doos van zijn beroemde tabak nog heel is...$B$BWat zeg je ervan, $N? Vind je een doos voor de oude Smokey?",
  o = "Vind de rookwarenwinkel van Fras Siabi in Stratholme en haal een doos Siabi's Premium Tobacco op. Ga terug naar Smokey LaRue als het klusje gedaan is.$b",
  p = "Ik hou het niet uit, $N! Je moet me helpen! Ik ga dood!$b",
  c = "O, lieve, lieve sigaar, wat heb ik je gemist...",
  g = { {"geplunderd", "sacked, looted (plunderen)"}, {"kostbare", "precious (kostbaar)"}, {"waren", "goods, wares"}, {"achterlaten", "to leave behind"}, {"verdomde", "damned (verdomd)"}, {"smerige", "dirty, filthy (smerig)"}, {"sigaar", "cigar, stogie"}, {"omgekomen", "perished (omkomen)"}, {"rookwarenwinkel", "tobacco shop, smoke shop"}, {"ik hou het niet uit", "I can't take it"} },
},

[5243] = { en = "Houses of the Holy", tier = 4,
  t = "Huizen van het heilige",
  d = "Ik zie mijn ondood als een kwaal, $r. Een ziekte die alleen behandeling nodig heeft. Toch is het ook een grote zegen voor de Argent Dawn. Wat is een beter middel om de heidenen van de Scourge te verslaan dan de ondoden zelf?$B$BMijn collega's vereren me vanwege de offers die ik heb gebracht, maar de lof betekent niets voor me.$B$BAls je de Argent Dawn wilt helpen, dan kan ik je een klus aanbieden.$B$BGa naar Stratholme en haal onze voorraad wijwater terug. Doorzoek de voorraadkisten.$b",
  o = "Reis naar Stratholme, in het noorden. Doorzoek de voorraadkisten die overal in de stad liggen en haal 5 Stratholme Holy Water op. Ga terug naar Leonid Barthalomew the Revered als je genoeg van de gezegende vloeistof hebt verzameld.",
  p = "Wees voorzichtig: niet alle voorraadkisten hebben de verwoesting van de stad overleefd. De Scourge durft het water niet aan te raken, maar het wijwater houdt zeker geen ongedierte tegen.$b",
  c = "Goed gedaan, $r. Je hebt bewezen dat je verdraagzaam bent tegenover anderen, maar dat je voor niets terugdeinst om de dienaren van Kel'Thuzad te vernietigen.$b",
  g = { {"ondood", "undeath"}, {"kwaal", "malady, ailment"}, {"behandeling", "treatment"}, {"heidenen", "heathens (heiden)"}, {"vereren", "revere (vereren)"}, {"offers", "sacrifices (offer)"}, {"lof", "praise, accolades"}, {"wijwater", "holy water"}, {"voorraadkisten", "supply crates (voorraadkist)"}, {"gezegende", "blessed (gezegend)"}, {"verwoesting", "destruction"}, {"ongedierte", "vermin"}, {"verdraagzaam", "tolerant"}, {"terugdeinst", "shrink back, stop (terugdeinzen)"}, {"dienaren", "minions, servants (dienaar)"} },
},

[5251] = { en = "The Archivist", tier = 4,
  t = "De archivaris",
  d = "Alles wat tot het uiterste wordt doorgedreven, is gevaarlijk voor onze wereld, $N. Neem bijvoorbeeld de Scarlet Crusade. Geloof je dat hun blinde dweperij een groter goed dient? Hoeveel onschuldigen hebben ze vernietigd in de naam van het Licht?$B$BGodslasteraars, allemaal!$B$BEén van hen interesseert me in het bijzonder: Archivist Galford van Stratholme. Een man die waakt over de kostbaarste documenten van de Crusade. Vernietig hem en brand zijn archief plat! Als het je lukt, kom dan terug naar mij en je wordt beloond.",
  o = "Reis naar Stratholme en vind Archivist Galford van de Scarlet Crusade. Vernietig hem en brand het Scarlet Archive plat.",
  p = "Onthoud, $N: we moeten verdraagzaam zijn, maar standvastig in wat we geloven!",
  c = "Uitstekend, $N! Jaren aan inlichtingen, verloren! De Scarlet Crusade zal deze klap de komende weken zeker voelen.",
  o2 = "Archief verbrand",
  g = { {"tot het uiterste", "to the extreme"}, {"doorgedreven", "pushed, taken (doordrijven)"}, {"dweperij", "zealotry, fanaticism"}, {"onschuldigen", "innocents (onschuldige)"}, {"godslasteraars", "blasphemers (godslasteraar)"}, {"in het bijzonder", "in particular"}, {"waakt", "watches over (waken)"}, {"archief", "archive"}, {"plat branden", "to burn down"}, {"standvastig", "steadfast, rigid"}, {"inlichtingen", "intelligence, information"}, {"klap", "blow"} },
},

[5262] = { en = "The Truth Comes Crashing Down", tier = 4,
  t = "De waarheid stort in",
  d = "Je probeert je gedachten te ordenen terwijl het stof in de zaal neerdaalt. Je denkt na over wat er net is gebeurd, maar je kunt nog steeds niet begrijpen hoe ernstig de situatie is.$B$BDe Grand Crusader van de Scarlet Crusade een demon? En niet zomaar een demon, maar de broer van Varimathras, aartsheer van de Undercity?$B$BVoorzichtig stop je het afgehakte hoofd van de dreadlord in je tas. Zonder bewijs zou niemand je verhaal geloven.$B$BDuke Nicholas Zverenhoff moet het meteen horen!",
  o = "Breng de Head of Balnazzar naar Duke Nicholas Zverenhoff in de Eastern Plaguelands.",
  p = "Wat heb je daar, $N?",
  c = "Wat zal dit betekenen voor de Crusade? Zou het kunnen dat ze onder de macht van deze demon stonden? Dat ze, zonder het te weten, als pionnen dienden van een groter kwaad?",
  g = { {"ordenen", "to put in order, gather"}, {"neerdaalt", "settles (neerdalen)"}, {"ernstig", "grave, serious"}, {"aartsheer", "arch lord"}, {"afgehakte", "severed (afhakken)"}, {"bewijs", "proof"}, {"onder de macht", "under the control"}, {"pionnen", "pawns (pion)"}, {"kwaad", "evil"} },
},

[5263] = { en = "Above and Beyond", tier = 4,
  t = "Boven en voorbij",
  d = "Je toont een natuurlijk talent voor vernietiging, en je volgt bevelen op. Het is zeldzaam dat die twee samengaan. Ik begin te denken dat je een uitstekend werktuig van goddelijke gerechtigheid zou kunnen zijn.$B$B<Zverenhoff vouwt zijn handen samen voor zijn gezicht.>$B$BHet loopjongetje van Kel'Thuzad heerst over Stratholme. Bewijs me dat je een kampioen bent, mijn kampioen. Vernietig Baron Rivendare en kom terug met zijn hoofd.$b",
  o = "Ga naar Stratholme en vernietig Baron Rivendare. Neem zijn hoofd mee en ga terug naar Duke Nicholas Zverenhoff.$b",
  p = "De baron heeft meer mensen gedood dan jij waarschijnlijk in je hele leven hebt gezien.",
  c = "Het is vele jaren geleden dat ik een kampioen in onze rangen heb opgenomen. Jij bent de eerste in jaren die een audiëntie bij Lord Maxwell krijgt.",
  g = { {"bevelen", "orders (bevel)"}, {"zeldzaam", "rare"}, {"samengaan", "to coexist, go together"}, {"werktuig", "instrument, vehicle"}, {"goddelijke", "divine (goddelijk)"}, {"gerechtigheid", "justice"}, {"vouwt", "folds, clasps (vouwen)"}, {"loopjongetje", "errand boy"}, {"heerst", "rules (heersen)"}, {"rangen", "ranks (rang)"}, {"audiëntie", "audience (with a ruler)"} },
},

[5282] = { en = "The Restless Souls", tier = 4,
  t = "De rusteloze zielen",
  d = "Ik haal mijn kracht, mijn wil om te blijven leven en ademen, uit de pure haat die ik voel voor de Scourge en alles wat ze hebben gedaan. Toch ben ik geen fanaticus. Er zijn mensen, zoals de Scarlet Crusade, die de onschuldige ondoden liever vernietigen dan dat ze hun ook maar een greintje medeleven geven.$B$BEn dat brengt me hierop: mijn blaster. Die maakt de gekwelde zielen van Stratholme los.$B$BGebruik hem op de geesten die door de geplunderde straten spoken. Bevrijd hun zielen.",
  o = "Gebruik Egan's Blaster op de spookachtige burgers van Stratholme. Als de rusteloze zielen uit hun spookachtige omhulsel loskomen, gebruik je de blaster opnieuw: dan worden ze vrij!$B$BBevrijd 15 Restless Souls en ga terug naar Egan.",
  p = "Medeleven is wat ons onderscheidt van de dieren, $N. Onthoud dat...",
  c = "<Egan veegt een traan uit zijn oog.>$B$BHeb je mijn moeder gezien, $N? Heb je haar bevrijd?$B$BJij bent een stralend voorbeeld van fatsoen. Voor je moeite...$b",
  o1 = "Zielen bevrijd",
  g = { {"rusteloze", "restless (rusteloos)"}, {"haat", "hatred"}, {"fanaticus", "zealot, fanatic"}, {"greintje", "ounce, scrap"}, {"medeleven", "compassion"}, {"gekwelde", "tortured (kwellen)"}, {"spoken", "haunt (spoken)"}, {"bevrijd", "free (bevrijden)"}, {"spookachtige", "ghostly (spookachtig)"}, {"omhulsel", "shell, casing"}, {"onderscheidt", "separates, distinguishes (onderscheiden)"}, {"veegt", "wipes (vegen)"}, {"stralend", "shining"}, {"fatsoen", "decency"} },
},

[5463] = { en = "Menethil's Gift", tier = 4,
  t = "Het geschenk van Menethil",
  d = "Ik zag hoe de mens Ras Frostwhisper zijn onsterfelijke ziel aan de Lich King beloofde. Hij zette de dolk op zijn eigen keel en sneed, met een glimlach, van oor tot oor. Zijn lichaam viel neer binnen de randen van het pentagram. De Lich King stond boven de gevallen magiër, en met één enkele beweging werd Ras Frostwhisper de lich geboren.$B$B<Leonid staart naar de grond en kijkt dan naar je op.>$B$BJa, $r, ik herinner het me. Wat je zoekt heeft een naam: Menethil's Gift. De grond die door de Lich King is gezegend, heilige grond voor de Scourge.$b",
  o = "Reis naar Stratholme en vind Menethil's Gift. Leg de Keepsake of Remembrance op de onheilige grond.",
  p = "Het gebied rond Menethil's Gift is uitzonderlijk koud.",
  c = "Je legt het aandenken op de besmette grond.",
  g = { {"onsterfelijke", "undying, immortal (onsterfelijk)"}, {"dolk", "dagger"}, {"keel", "throat"}, {"sneed", "cut (snijden)"}, {"randen", "borders, edges (rand)"}, {"magiër", "mage"}, {"beweging", "motion"}, {"staart", "gazes, stares (staren)"}, {"onheilige", "unholy (onheilig)"}, {"uitzonderlijk", "exceptionally"}, {"aandenken", "keepsake"} },
},

[5848] = { en = "Of Love and Family", tier = 4,
  t = "Over liefde en familie",
  d = "Het schilderij... Het hing jarenlang aan de muur van mijn werkplaats, in de kazerne van de Orde.$B$BNa het proces van Tirion wist ik dat ik het schilderij niet langer zichtbaar kon houden. Ik verstopte het op een plek waar ze nooit zouden kijken.$B$BReis naar Stratholme en ga diep naar binnen in wat nu de Scarlet Bastion is. Zoek naar een schilderij van onze twee manen. Schraap de verf weg tot je mijn meesterwerk vindt: 'Of Love and Family'.$B$BMoge het Licht je daden leiden.",
  o = "Reis naar Stratholme, in het noordelijke deel van de Plaguelands. In de Scarlet Bastion vind je het schilderij 'Of Love and Family'. Het is verstopt achter een ander schilderij, dat de twee manen van onze wereld laat zien.$B$BBreng het schilderij terug naar Tirion Fordring.",
  p = "Het schilderij, $N. Heb je het schilderij?",
  c = "<Tirion zakt bijna in elkaar als hij het schilderij ziet.>$B$B<Hij begint bijna wild te snikken.>",
  g = { {"schilderij", "painting"}, {"werkplaats", "workshop"}, {"kazerne", "barracks"}, {"proces", "trial"}, {"zichtbaar", "visible"}, {"verstopte", "hid (verstoppen)"}, {"manen", "moons (maan)"}, {"schraap", "scrape, chip (schrapen)"}, {"meesterwerk", "masterpiece"}, {"daden", "actions, deeds (daad)"}, {"zakt in elkaar", "collapses (in elkaar zakken)"}, {"snikken", "to sob"} },
},

[6643] = { en = "Favor Amongst the Brotherhood, Fiery Core", tier = 4,
  t = "Gunst bij de Brotherhood: Fiery Core",
  p = "Wee hen die in de Molten Core het lot tarten. De dood komt snel, en de straf wordt zonder genade uitgedeeld.$B$BVeel leden van de Brotherhood zijn omgekomen tijdens hun zoektocht naar Fiery Cores.$B$BBied 1 Fiery Core aan, en je krijgt gunst bij de Brotherhood.",
  c = "Je offer is aanvaard. Gunst heb je verdiend. Ga zo door, en je krijgt toegang tot de oude ambachten.",
  g = { {"gunst", "favour"}, {"wee hen", "woe unto those"}, {"lot", "fate"}, {"tarten", "to tempt, to defy"}, {"straf", "punishment"}, {"genade", "mercy"}, {"uitgedeeld", "dealt (uitdelen)"}, {"bied aan", "offer (aanbieden)"}, {"offer", "offering"}, {"aanvaard", "accepted (aanvaarden)"}, {"ambachten", "trades, crafts (ambacht)"} },
},

[6644] = { en = "Favor Amongst the Brotherhood, Lava Core", tier = 4,
  t = "Gunst bij de Brotherhood: Lava Core",
  p = "De Thorium Brotherhood heeft begrip voor jouw benarde situatie, $R. Daarom heeft Lokthos de macht gekregen om te onderhandelen.$B$BBied 1 Lava Core aan, en je krijgt gunst bij de Brotherhood.",
  c = "Je offer is aanvaard. Gunst heb je verdiend. Ga zo door, en je krijgt toegang tot de oude ambachten.",
  g = { {"gunst", "favour"}, {"begrip", "sympathy, understanding"}, {"benarde", "dire, distressing (benard)"}, {"onderhandelen", "to bargain, negotiate"}, {"bied aan", "offer (aanbieden)"}, {"offer", "offering"}, {"aanvaard", "accepted (aanvaarden)"}, {"ambachten", "trades, crafts (ambacht)"} },
},

[6822] = { en = "The Molten Core", tier = 4,
  t = "De Molten Core",
  d = "$n, misschien is het tijd om je een echte test te geven. Ben je er klaar voor?$B$BOnderaan Blackrock Depths is een doorgang naar de Molten Core. Dat is een vesting van onze vijand, in handen van de machtigste dienaren van het vuur op deze wereld.$B$BGa naar de Molten Core, $N. Laat me zien dat je de kracht en de wil hebt om te verslaan wat je daar vindt.$B$BEn als je bondgenoten hebt onder je eigen volk, verzamel ze dan. Alleen een heel leger kan hopen de Molten Core binnen te gaan en levend terug te komen.",
  o = "Dood 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound en 1 Lava Surger, en ga dan terug naar Duke Hydraxis in Azshara.",
  p = "Je succes in de Molten Core wacht op je, $N.",
  c = "Je hebt gedaan wat de meesten van jouw soort onmogelijk zouden vinden. Je hebt de wezens van de Molten Core getrotseerd, en je hebt gezegevierd!$B$BVoor zo'n klein wezen heb je veel vindingrijkheid getoond.$B$BOp een dag kunnen we misschien een echt bondgenootschap sluiten tussen jouw soort en de Waterlords.",
  g = { {"doorgang", "passage"}, {"vesting", "stronghold, fortress"}, {"machtigste", "most powerful (machtig)"}, {"bondgenoten", "allies (bondgenoot)"}, {"leger", "army"}, {"getrotseerd", "faced, braved (trotseren)"}, {"gezegevierd", "triumphed (zegevieren)"}, {"vindingrijkheid", "resourcefulness"}, {"bondgenootschap", "allegiance, alliance"}, {"sluiten", "to make (an alliance), to close"} },
},

[6824] = { en = "Hands of the Enemy", tier = 4,
  t = "Handen van de vijand",
  d = "$N, jouw diensten zijn veel waard voor ons. Daarom sturen we je niet graag op deze laatste missie, want we willen zo'n nuttige agent niet verliezen.$B$BMaar als ze slaagt, helpt dat onze oorlog enorm vooruit en... men vond het het risico waard.$B$BWe willen dat deze aanvoerders in de Molten Core worden vernietigd: Lucifron, Sulfuron, Gehennas en Shazzrah. Dood ze en breng me hun handen!$B$BVoor deze taak heb je alle middelen nodig die je hebt, $N. Maar als het je lukt, krijgen de Firelords een vreselijke klap.",
  o = "Breng de Hands of Lucifron, Sulfuron, Gehennas en Shazzrah naar Duke Hydraxis in Azshara.",
  p = "Heb je Lucifron en de anderen verslagen, $N? Heb je de handen van de vijand?",
  c = "Je hebt de handen! Je hebt de vuuraanvoerders verslagen! Ik had het niet voor mogelijk gehouden als ik jou niet kende en niet wist waartoe je in staat bent.$B$B$N, je heldendaden zijn niet te tellen, maar het nieuws over deze laatste prestatie zal golven veroorzaken onder de Waterlords. Je naam wordt misschien ooit een legende voor ons.$B$BPraat nog eens met me, $N. Misschien heb ik nog een taak...",
  g = { {"diensten", "service (dienst)"}, {"nuttige", "useful (nuttig)"}, {"slaagt", "succeeds (slagen)"}, {"aanvoerders", "captains, leaders (aanvoerder)"}, {"middelen", "resources (middel)"}, {"klap", "blow"}, {"voor mogelijk gehouden", "thought possible"}, {"in staat", "capable"}, {"heldendaden", "exploits, heroic deeds (heldendaad)"}, {"prestatie", "feat, achievement"}, {"golven", "waves (golf)"}, {"legende", "legend"} },
},

[7521] = { en = "Thunderaan the Windseeker", tier = 4,
  t = "Thunderaan the Windseeker",
  d = "Ik heb je alles verteld wat ik weet, $N. Jij bent degene die elementium moet vinden. Jij bent degene die het stoffelijke lichaam van de Firelord moet vernietigen.$B$BDoe dit en ontvang de zegen van Thunderaan.",
