[8578] = { en = "Scrying Goggles? No Problem!", tier = 4,
  t = "Scrying Goggles? Geen probleem!",
  d = "<Je hoort een zucht van opluchting uit de kist komen.>$B$BJe wilt alleen zijn helderziende bril? Geweldig! Dat is geen probleem... Geef me even een minuutje om... Hé! Waar is... Verdorie!$B$BNou, er is slecht nieuws en nog slechter nieuws. Het slechte nieuws is dat ik de bril kwijt ben. Het nog slechtere nieuws is dat ik hem kwijtraakte toen ik vorige maand in de Molten Core rondsnuffelde. Ja, de Molten Core... Dan zijn we wel klaar met zaken doen, denk ik! Dag!",
  o = "Vind Narain's Scrying Goggles en breng ze terug naar Narain Soothfancy in Tanaris.",
  p = "De Molten Core, hè? Ik hoop dat mijn bril nog heel is!",
  c = "Uitstekend! Waar heb ik nu die kip van 500 pond gelaten, en Deel II van \"Draconic For Dummies???\" O, en hier is iets kleins voor al je harde werk!",
  g = { {"zucht", "sigh"}, {"opluchting", "relief"}, {"helderziende", "scrying, clairvoyant (helderziend)"}, {"bril", "goggles, glasses"}, {"verdorie", "dagnabbit, darn"}, {"kwijtraakte", "lost (kwijtraken)"}, {"rondsnuffelde", "was nosing around (rondsnuffelen)"}, {"zaken doen", "to do business"}, {"pond", "pound"}, {"deel", "volume, part"} },
},

[8968] = { en = "The Left Piece of Lord Valthalak's Amulet", tier = 4,
  t = "Het linkerdeel van Lord Valthalaks amulet",
  d = "De broer en zus Jarien en Sothos besloten zich bij de Scarlet Crusade aan te sluiten toen onze huurlingengroep uit elkaar ging. Ze namen het linkerdeel van Lord Valthalaks amulet mee. Opgeruimd staat netjes, zeg ik, maar we hebben dat stuk terug nodig.$B$BVoor zover wij weten, zijn ze zelfs door Grand Crusader Dathrohan zelf gedood. Ze faalden bij de inwijdingsrituelen in zijn zaal in de Scarlet Bastion.$B$BHoe dan ook, wij... dat wil zeggen jij, zult dat stuk van het amulet nog steeds moeten terughalen.",
  o = "Gebruik de Brazier of Beckoning om Jarien en Sothos op te roepen en dood ze. Ga terug naar Bodley in Blackrock Mountain met de Left Piece of Lord Valthalak's Amulet en de Brazier of Beckoning.",
  p = "Betekent dit dan, $C, dat je de zielen van die twee dwazen al te ruste hebt gelegd en het linkerdeel van Lord Valthalaks amulet hebt teruggehaald?",
  c = "Het is waarschijnlijk maar het beste dat de zielen van die twee eindelijk rust hebben gevonden, ook al mocht ik ze niet toen ze nog leefden. Hoe dan ook, we hebben wat we zochten, en dat is zeker een goede zaak!$B$BHelaas weet ik niet waar degene is die stierf met het rechterdeel van het amulet in bezit. Maar wees niet bang. Toen ik nog leefde, hield ik me een beetje bezig met de kunst van het waarzeggen. Daarom heb ik nog een taak voor je, waarmee we het laatste stuk kunnen opsporen.",
  g = { {"huurlingengroep", "mercenary company"}, {"uit elkaar ging", "disbanded (uit elkaar gaan)"}, {"opgeruimd staat netjes", "good riddance"}, {"faalden", "failed (falen)"}, {"inwijdingsrituelen", "initiation rites"}, {"op te roepen", "to summon (oproepen)"}, {"dwazen", "fools (dwaas)"}, {"te ruste gelegd", "put to rest"}, {"in bezit", "in possession"}, {"waarzeggen", "divination, fortune-telling"}, {"opsporen", "to track down, ferret out"} },
},

[8991] = { en = "The Right Piece of Lord Valthalak's Amulet", tier = 4,
  t = "Het rechterdeel van Lord Valthalaks amulet",
  d = "De broer en zus Jarien en Sothos besloten zich bij de Scarlet Crusade aan te sluiten toen onze huurlingengroep uit elkaar ging. Ze namen het rechterdeel van Lord Valthalaks amulet mee. Opgeruimd staat netjes, zeg ik, maar we hebben dat stuk terug nodig.$B$BVoor zover wij weten, zijn ze zelfs door Grand Crusader Dathrohan zelf gedood. Ze faalden bij de inwijdingsrituelen in zijn zaal in de Scarlet Bastion.$B$BHoe dan ook, wij... dat wil zeggen jij, zult dat stuk van het amulet nog steeds moeten terughalen.",
  o = "Gebruik de Brazier of Beckoning om Jarien en Sothos op te roepen en dood ze. Ga terug naar Bodley in Blackrock Mountain met de weer samengevoegde Lord Valthalak's Amulet en de Brazier of Beckoning.",
  p = "Betekent dit dan, $C, dat je de zielen van die twee dwazen al te ruste hebt gelegd en de stukken van Lord Valthalaks amulet weer hebt samengevoegd?",
  c = "Het is waarschijnlijk maar het beste dat de zielen van die twee eindelijk rust hebben gevonden, ook al mocht ik ze niet toen ze nog leefden. Hoe dan ook, we hebben wat we zochten, en nu is het amulet weer heel! Maar de zwaarste proef ligt nog voor ons.$B$BOm het komfoor af te stemmen op het oproepen van Lord Valthalak, moeten er nog een paar voorwerpen worden verzameld en hier naar mij worden gebracht.",
  g = { {"huurlingengroep", "mercenary company"}, {"opgeruimd staat netjes", "good riddance"}, {"inwijdingsrituelen", "initiation rites"}, {"samengevoegde", "recombined (samenvoegen)"}, {"dwazen", "fools (dwaas)"}, {"te ruste gelegd", "put to rest"}, {"proef", "test, trial"}, {"komfoor", "brazier"}, {"af te stemmen", "to attune (afstemmen)"}, {"oproepen", "to summon"} },
},

